Arguments: {"cwd":null,"code":"const tabId = 480038377;
// Let's search on Etsy
await tool.navigate({ tabId, url: "https://www.etsy.com/search?q=personalized+family+christmas+ornament" });
await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });

const searchResults = await browserjs(tabId, () => {
  // Look for listing cards
  const cards = Array.from(document.querySelectorAll('a[href*="/listing/"]'));
  const results = [];
  const seen = new Set();
  for (const a of cards) {
    const href = a.href.split('?')[0];
    if (seen.has(href)) continue;
    seen.add(href);
    const title = a.querySelector('h3')?.innerText?.trim() || a.getAttribute('title') || a.innerText?.trim();
    const priceEl = a.closest('div[class*="listing"]') || a.parentElement;
    const priceText = priceEl?.innerText || "";
    if (title && href.includes('/listing/')) {
      results.push({ href, title: title.slice(0, 100), fullText: priceText.slice(0, 200) });
    }
    if (results.length >= 10) break;
  }
  return { url: window.location.href, count: results.length, results };
});

console.log(JSON.stringify(searchResults, null, 2));
","title":"Search Etsy for personalized family christmas ornament"}
